"use strict";
exports.send = (input) => JSON.stringify(input);
exports.total = (names) => names.join("+");
exports.tableSize = (table) => table.size;
exports.useSink = (sink) => sink.take(2) + sink.take(3);
exports.makeNames = () => ["i1", "i2"];
exports.makeSink = () => ({
  name: "island",
  seen: 0,
  take(n) {
    this.seen += n;
    return this.seen;
  },
});
